# if doc.task_kind and len(assigned_users) == 1 and allowed_roles:
#     owner = assigned_users[0]
#     if not user_has_allowed_role(owner, allowed_roles):
#         frappe.throw("Task Kind '" + doc.task_kind + "' must be assigned to a user in: " + ", ".join(allowed_roles) + ".")
# if is_becoming_completed:
#     if len(assigned_users) != 1:
#         frappe.throw("Assign exactly 1 owner before completing this task.")
if is_becoming_completed and not doc.completed_at:
    doc.completed_at = frappe.utils.now_datetime()

if doc.director_approval_status != "Approved":
    frappe.throw(
        "Director approval is required before submitting the Purchase Order. "
        "Create a Purchase Approval task, get it completed as Approved, then submit."
    )

MAIN_WH = "Main - Inmed"

for row in (doc.items or []):
    if row.warehouse != MAIN_WH:
        frappe.throw(f"Receiving must be into {MAIN_WH}. Row warehouse is {row.warehouse or 'not set'}.")

    if not row.item_code:
        continue

    item = frappe.get_doc("Item", row.item_code)

    requires_expiry = bool(item.get("has_expiry_date"))
    has_batch = bool(item.get("has_batch_no"))

    if requires_expiry and has_batch:
        if not row.batch_no:
            frappe.throw(f"Row for item {row.item_code} requires Batch + Expiry. Batch No is missing.")

        batch = frappe.get_doc("Batch", row.batch_no)
        if not batch.expiry_date:
            frappe.throw(f"Batch {row.batch_no} must have Expiry Date for item {row.item_code}.")

if doc.supplier:
    for row in (doc.items or []):
        if not row.item_code:
            continue

        suppliers = frappe.get_all(
            "Item Supplier",
            filters={"parent": row.item_code, "parenttype": "Item"},
            pluck="supplier",
        )

        suppliers = [s for s in (suppliers or []) if s]

        if len(suppliers) != 1:
            frappe.throw(
                f"Item {row.item_code} must have exactly 1 Supplier (Doc 07 policy). Found: {', '.join(suppliers) or 'none'}."
            )

        if suppliers[0] != doc.supplier:
            frappe.throw(
                f"Item {row.item_code} supplier is {suppliers[0]} but PO supplier is {doc.supplier}. Do not mix suppliers on one PO."
            )

before = doc.get_doc_before_save()
if before:
    def snap(rows):
        return [(r.warehouse, r.warehouse_reorder_level or 0, r.warehouse_reorder_qty or 0) for r in (rows or [])]
    if snap(before.reorder_levels) != snap(doc.reorder_levels):
        if not (doc.reorder_change_reason or "").strip():
            frappe.throw("Doc 08: Reorder Change Reason required.")

before = doc.get_doc_before_save()

if not before:
    pass
else:
    # Standard ERPNext fieldname for Item Reorder child table.
    # If your instance uses a different name, change this value.
    REORDER_FIELDNAME = "reorder_levels"

    def normalize(rows):
        out = []
        for r in (rows or []):
            out.append({
                "warehouse": r.warehouse,
                "reorder_level": float(getattr(r, "warehouse_reorder_level", 0) or 0),
                "reorder_qty": float(getattr(r, "warehouse_reorder_qty", 0) or 0),
            })
        return out

    before_rows = normalize(before.get(REORDER_FIELDNAME) or [])
    after_rows  = normalize(doc.get(REORDER_FIELDNAME) or [])

    if before_rows != after_rows:
        if not (doc.reorder_change_reason or "").strip():
            frappe.throw(
                "Reorder Change Reason is required when changing reorder thresholds "
                "(Doc 08 governance rule)."
            )

DELIVERY_IN_TRANSIT_WH = "Delivery In-Transit - Inmed"

for row in (doc.items or []):
    if row.warehouse != DELIVERY_IN_TRANSIT_WH:
        frappe.throw(
            f"Standard sales Delivery Note must issue from {DELIVERY_IN_TRANSIT_WH}. "
            f"Row warehouse is {row.warehouse or 'not set'}."
        )

sales_orders = sorted(list(set([r.against_sales_order for r in (doc.items or []) if r.against_sales_order])))
for so_name in sales_orders:
    so = frappe.get_doc("Sales Order", so_name)

    if so.discount_approval_status in ("Pending", "Rejected"):
        frappe.throw("Discount approval is required before delivery.")

    if so.is_prepaid:
        if not so.prepayment_payment_entry:
            frappe.throw("Prepaid order requires Prepayment Payment Entry before delivery.")

        pe = frappe.get_doc("Payment Entry", so.prepayment_payment_entry)
        if pe.docstatus != 1:
            frappe.throw("Prepayment Payment Entry must be submitted before delivery.")

if doc.stock_entry_type == "Material Transfer":
    MAIN_WH = "Main - Inmed"
    DELIVERY_IN_TRANSIT_WH = "Delivery In-Transit - Inmed"

    to_wh = doc.get("to_warehouse")
    from_wh = doc.get("from_warehouse")
    row_targets = [(r.get("s_warehouse"), r.get("t_warehouse")) for r in (doc.get("items") or [])]

    is_dispatch_staging = (
        (from_wh == MAIN_WH and to_wh == DELIVERY_IN_TRANSIT_WH)
        or any((s == MAIN_WH and t == DELIVERY_IN_TRANSIT_WH) for (s, t) in row_targets)
    )

    if is_dispatch_staging:
        if not doc.sales_order:
            frappe.throw("Dispatch staging Stock Entry must be linked to a Sales Order.")

        so = frappe.get_doc("Sales Order", doc.sales_order)

        if so.discount_approval_status in ("Pending", "Rejected"):
            frappe.throw(
                "Discount approval is required before dispatch staging. "
                "Complete the Discount Approval task (Approved) or remove the discount."
            )

        tasks = frappe.get_all(
            "Task",
            filters={
                "task_kind": "Delivery",
                "sales_order": so.name,
                "status": ["!=", "Cancelled"],
            },
            fields=["name", "warehouse_pickup_photo"],
        )

        if not tasks:
            frappe.throw("Dispatch staging requires an existing Delivery Task linked to this Sales Order.")

        if not any(t.get("warehouse_pickup_photo") for t in tasks):
            frappe.throw("Warehouse Pickup Photo must be attached to the Delivery Task before dispatch staging.")

        if so.is_prepaid:
            if not so.prepayment_payment_entry:
                frappe.throw("Prepaid order requires Prepayment Payment Entry before dispatch staging.")

            pe = frappe.get_doc("Payment Entry", so.prepayment_payment_entry)
            if pe.docstatus != 1:
                frappe.throw("Prepayment Payment Entry must be submitted before dispatch staging.")

            required = float(so.prepayment_required_amount_amd or 0)
            if required > 0:
                paid = float(pe.paid_amount or 0)
                if paid < required:
                    frappe.throw("Prepayment amount is below required amount for this order.")

CLIENTS_ROOT = "Clients - Inmed"

if doc.get("sales_order"):
    root = frappe.get_doc("Warehouse", CLIENTS_ROOT)
    root_lft = int(root.lft)
    root_rgt = int(root.rgt)

    for row in (doc.items or []):
        wh = row.t_warehouse or doc.get("to_warehouse")
        if wh:
            is_client_wh = frappe.db.exists(
                "Warehouse",
                {"name": wh, "lft": [">=", root_lft], "rgt": ["<=", root_rgt]},
            )

            if is_client_wh:
                frappe.throw("Standard sales must not move stock into client location warehouses (Clients - Inmed).")

before = doc.get_doc_before_save()
before_status = before.status if before else None

is_becoming_completed = (doc.status == "Completed" and before_status != "Completed")

if is_becoming_completed and doc.task_kind == "Return drop-off at warehouse":
    has_dropoff = doc.warehouse_dropoff_photo or frappe.db.exists("File", {"attached_to_doctype": "Task", "attached_to_name": doc.name, "attached_to_field": "warehouse_dropoff_photo"})
    if not has_dropoff:
        frappe.throw("Warehouse Drop-off Photo is required to complete this task.")

    if not doc.completed_at:
        doc.completed_at = now_datetime()

DIRECTOR_ROLE = "Ops - Directors"

def is_manual_rate_override(row):
    price_list_rate = float(row.get("price_list_rate") or 0)
    discount_pct = float(row.get("discount_percentage") or 0)
    rate = float(row.get("rate") or 0)

    # If there is no price list rate, do NOT treat entered rate as manual override.
    # Otherwise every item with price_list_rate = 0 and normal entered rate would require approval.
    if price_list_rate <= 0:
        return False

    expected = price_list_rate * (1 - (discount_pct / 100.0))
    return abs(rate - expected) > 0.01


def assign_single_owner(task_name, user):
    # Use frappe.as_json instead of json.dumps because json may not be available in Server Script safe_exec.
    frappe.db.set_value(
        "Task",
        task_name,
        "_assign",
        frappe.as_json([user]),
        update_modified=False
    )

    other_todos = frappe.get_all(
        "ToDo",
        filters={
            "reference_type": "Task",
            "reference_name": task_name,
            "allocated_to": ["!=", user],
            "status": "Open",
        },
        pluck="name",
    )

    for td in (other_todos or []):
        frappe.db.set_value("ToDo", td, "status", "Cancelled")

    if not frappe.db.exists(
        "ToDo",
        {
            "reference_type": "Task",
            "reference_name": task_name,
            "allocated_to": user,
            "status": "Open",
        },
    ):
        todo = frappe.new_doc("ToDo")
        todo.status = "Open"
        todo.allocated_to = user
        todo.reference_type = "Task"
        todo.reference_name = task_name
        todo.description = frappe.db.get_value("Task", task_name, "subject") or task_name
        todo.assigned_by = frappe.session.user
        todo.insert(ignore_permissions=True)


def user_has_role(role):
    return bool(
        frappe.db.exists(
            "Has Role",
            {
                "parent": frappe.session.user,
                "role": role,
            }
        )
    )


def has_discount(doc, is_manual_rate_override=is_manual_rate_override):
    if float(doc.get("additional_discount_percentage") or 0) != 0:
        frappe.throw(
            "Do not use header-level additional discount. "
            "Use per-line Discount Percentage so approvals and reporting stay consistent."
        )

    for row in (doc.items or []):
        if float(row.get("discount_percentage") or 0) > 0:
            return True

        if is_manual_rate_override(row):
            return True

    return False


def has_manual_pricing(doc, is_manual_rate_override=is_manual_rate_override):
    for row in (doc.items or []):
        if is_manual_rate_override(row):
            return True

    return False


def discount_signature(doc):
    sig = {
        "additional_discount_percentage": float(doc.get("additional_discount_percentage") or 0),
        "items": [],
    }

    for row in (doc.items or []):
        sig["items"].append({
            "item_code": row.get("item_code"),
            "discount_percentage": float(row.get("discount_percentage") or 0),
            "rate": float(row.get("rate") or 0),
            "price_list_rate": float(row.get("price_list_rate") or 0),
        })

    return sig


before = doc.get_doc_before_save()
discount_present = has_discount(doc)

if not discount_present:
    doc.discount_approval_status = "Not Required"
    doc.discount_approval_task = None
    doc.discount_approval_note = None

    open_tasks = frappe.get_all(
        "Task",
        filters={
            "task_kind": "Discount Approval",
            "sales_order": doc.name,
            "status": ["!=", "Completed"],
        },
        pluck="name",
    )

    for tname in (open_tasks or []):
        desc = frappe.db.get_value("Task", tname, "description") or ""
        note = "Cancelled automatically: discount removed from Sales Order."

        if note not in desc:
            desc = (desc + "\n" if desc else "") + note
            frappe.db.set_value("Task", tname, "description", desc)

        frappe.db.set_value("Task", tname, "status", "Cancelled")

        todos = frappe.get_all(
            "ToDo",
            filters={
                "reference_type": "Task",
                "reference_name": tname,
                "status": "Open",
            },
            pluck="name",
        )

        for td in (todos or []):
            frappe.db.set_value("ToDo", td, "status", "Cancelled")

else:
    sig_preserved = False

    if before and before.get("discount_approval_status") in ("Approved", "Rejected"):
        before_sig = discount_signature(before)
        after_sig = discount_signature(doc)

        if before_sig == after_sig:
            doc.discount_approval_status = before.discount_approval_status
            doc.discount_approval_task = before.discount_approval_task
            doc.discount_approval_note = before.discount_approval_note
            sig_preserved = True

    if not sig_preserved:
        doc.discount_approval_status = "Pending"
        doc.discount_approval_task = None
        doc.discount_approval_note = None

        if has_manual_pricing(doc):
            if not (
                user_has_role("Ops - Accounting")
                or user_has_role("Ops - Directors")
            ):
                frappe.throw(
                    "Manual rate changes are allowed only for Accounting/Directors (Doc 09 policy)."
                )

            if not (doc.manual_pricing_reason or "").strip():
                frappe.throw(
                    "Manual Pricing Reason is required when any line rate is manually overridden."
                )

        existing = frappe.get_all(
            "Task",
            filters={
                "task_kind": "Discount Approval",
                "sales_order": doc.name,
                "status": ["!=", "Completed"],
            },
            pluck="name",
        )

        if existing:
            doc.discount_approval_task = existing[0]

        else:
            subject = "Discount Approval - SO " + doc.name

            task = frappe.new_doc("Task")
            task.subject = subject
            task.status = "Open"
            task.task_kind = "Discount Approval"
            task.task_access_policy = "Discount Approval"
            task.sales_order = doc.name
            task.customer = doc.customer

            task.insert(ignore_permissions=True)

            director_users = frappe.get_all(
                "Has Role",
                filters={
                    "role": DIRECTOR_ROLE,
                },
                pluck="parent",
            )

            director_users = sorted(list(set(director_users or [])))

            director_users = [
                u
                for u in director_users
                if u not in ("Administrator", "Guest")
                and int(frappe.db.get_value("User", u, "enabled") or 0) == 1
            ]

            if not director_users:
                frappe.throw(
                    "No director users found. Create at least one User with role '"
                    + DIRECTOR_ROLE
                    + "'."
                )

            assign_single_owner(task.name, director_users[0])
            doc.discount_approval_task = task.name

def run_script(doc):
    MAIN_WH           = "Main - Inmed"
    DELIVERY_WH       = "Delivery In-Transit - Inmed"
    RETURN_TRANSIT_WH = "Return Pickup In-Transit - Inmed"
    RETURNS_WH        = "Returns - Inmed"

    def split_serials(s):
        if not s: return []
        return [x.strip() for x in str(s).split("\n") if x.strip()]

    def get_bin_qty(item_code, warehouse):
        return float(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty") or 0)

    def make_transfer(items, s_wh, t_wh, posting_dt=None):
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Transfer"
        if posting_dt:
            se.set_posting_time = 1
            if hasattr(posting_dt, "date"):
                se.posting_date = posting_dt.date()
                se.posting_time = posting_dt.time()
            else:
                parts = str(posting_dt).split(" ")
                se.posting_date = parts[0]
                if len(parts) > 1: se.posting_time = parts[1].split(".")[0]
        for it in items:
            row = {"item_code": it["item_code"], "qty": it["qty"], "s_warehouse": s_wh, "t_warehouse": t_wh}
            if it.get("batch_no"):  row["batch_no"]  = it["batch_no"]
            if it.get("serial_no"): row["serial_no"] = it["serial_no"]
            se.append("items", row)
        if hasattr(se, "surgery_case"): se.surgery_case = doc.name
        if hasattr(se, "dispatch_group_id") and doc.dispatch_group_id:
            se.dispatch_group_id = doc.dispatch_group_id
        se.insert(ignore_permissions=True)
        return se

    def make_task(subject, task_kind, assign_user):
        t = frappe.new_doc("Task")
        t.subject = subject
        t.task_kind = task_kind
        t.task_access_policy = task_kind
        if hasattr(t, "surgery_case"): t.surgery_case = doc.name
        if hasattr(t, "customer"):     t.customer = doc.client
        if doc.dispatch_group_id:      t.dispatch_group_id = doc.dispatch_group_id
        if assign_user: t._assign = json.dumps([assign_user])
        t.insert(ignore_permissions=True)
        return t.name

    before       = doc.get_doc_before_save()
    before_state = (before.workflow_state if before else None) or "Draft"
    after_state  = doc.workflow_state or "Draft"
    state_changed = (before_state != after_state)

    # Auto-load template items on new case
    if after_state == "Draft" and doc.surgery_set_type and not (doc.case_items or []):
        st = frappe.get_doc("Surgery Set Type", doc.surgery_set_type)
        for r in (st.items or []):
            if r.item and float(r.default_qty or 0) > 0:
                doc.append("case_items", {"item": r.item, "dispatched_qty": float(r.default_qty),
                                          "returned_qty": 0, "lost_damaged_qty": 0, "used_qty": 0})

    # Draft: non-blocking stock shortage warning
    if after_state == "Draft":
        warnings = []
        for row in (doc.case_items or []):
            planned = float(row.dispatched_qty or 0)
            if planned > 0:
                avail = get_bin_qty(row.item, MAIN_WH)
                if avail < planned:
                    warnings.append(row.item + ": planned=" + str(planned) + " avail=" + str(avail))
        doc.shortage_note = ("Draft stock warning:\n" + "\n".join(warnings)) if warnings else ""
        if warnings: frappe.msgprint(doc.shortage_note, title="Stock warning (Draft)")

    if after_state != "Draft" and not doc.client_location_warehouse:
        frappe.throw("Client Location Warehouse is required.")

    CLIENT_WH = doc.client_location_warehouse or ""

    dispatch_items = [{"item_code": r.item, "qty": float(r.dispatched_qty or 0)}
                      for r in (doc.case_items or []) if float(r.dispatched_qty or 0) > 0]
    returned_items = [{"item_code": r.item, "qty": float(r.returned_qty or 0)}
                      for r in (doc.case_items or []) if float(r.returned_qty or 0) > 0]

    # Create delivery task when delivery_person first set (idempotent)
    if (doc.delivery_person and not doc.delivery_task
            and after_state not in ("Draft", "Preparing", "Dispatch Picking")):
        doc.delivery_task = make_task(
            "Deliver - " + doc.name, "Delivery", doc.delivery_person)

    # Create return tasks when person set in Return Pickup Scheduled (idempotent)
    if doc.return_pickup_delivery_person and after_state == "Return Pickup Scheduled":
        if not doc.return_pickup_task:
            doc.return_pickup_task = make_task(
                "Pickup Returns - " + doc.name, "Pickup Returns", doc.return_pickup_delivery_person)
        if not doc.return_dropoff_task:
            doc.return_dropoff_task = make_task(
                "Return drop-off - " + doc.name, "Return drop-off at warehouse",
                doc.return_pickup_delivery_person)

    if not state_changed: return

    # Preparing -> Dispatch Picking: stock gate + draft dispatch SE
    if before_state == "Preparing" and after_state == "Dispatch Picking":
        shortages = []
        for it in dispatch_items:
            avail = get_bin_qty(it["item_code"], MAIN_WH)
