today = getdate(nowdate())
valid_from = getdate(doc.valid_from) if doc.valid_from else None
valid_to = getdate(doc.valid_to) if doc.valid_to else None
if doc.status == "Draft":
    pass
elif valid_from and valid_to:
    if today < valid_from:
        doc.status = "Draft"
    elif today >= valid_from and today <= valid_to:
        doc.status = "Active"
    elif today > valid_to:
        doc.status = "Expired"

if doc.docstatus == 1:
    hospital = doc.customer
    tenders = frappe.get_all("Tender Agreement", 
        filters={"hospital": hospital, "status": "Active"},
        fields=["name"])
    if tenders:
        for inv_item in doc.items:
            item_code = inv_item.item_code
            qty = inv_item.qty or 0
            for tender_doc_name in [t.name for t in tenders]:
                tender = frappe.get_doc("Tender Agreement", tender_doc_name)
                for tender_item in tender.items:
                    if tender_item.item_code == item_code:
                        tender_item.supplied_quantity = (tender_item.supplied_quantity or 0) + qty
                        tender_item.remaining_quantity = (tender_item.won_quantity or 0) - tender_item.supplied_quantity
                tender.flags.ignore_permissions = True
                tender.save()
                frappe.db.commit()

before = doc.get_doc_before_save()
if before and before.status == 'Completed':
    frappe.throw('This task is already completed and cannot be modified.')

case_name = frappe.form_dict.get('case_name')
packed_json = frappe.form_dict.get('packed_indices') or '[]'
packed_indices = json.loads(packed_json)
task_kind = frappe.form_dict.get('task_kind') or ''

if not case_name:
        frappe.throw('Dispatch Case is required.')

case = frappe.get_doc('Dispatch Case', case_name)
is_returns = (task_kind == 'Returns processing / verification')

for idx, row in enumerate(case.case_items):
        required_qty = float(row.dispatched_qty or 0)
        if is_returns:
                if idx in packed_indices:
                        row.returned_qty = required_qty
                else:
                        row.returned_qty = 0
                row.used_qty = float(row.dispatched_qty or 0) - float(row.returned_qty or 0) - float(row.lost_damaged_qty or 0)
        else:
                if idx in packed_indices:
                        row.custom_scanned_qty = required_qty
                        row.custom_remaining_qty = 0
                        row.custom_packing_status = 'Complete'
                else:
                        row.custom_scanned_qty = 0
                        row.custom_remaining_qty = required_qty
                        row.custom_packing_status = 'Pending'

case.flags.ignore_permissions = True
case.save()

frappe.response['message'] = {'ok': True, 'total': len(case.case_items), 'packed': len(packed_indices)}
